window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-170e16829af019eb"]={"versions": [{"id": "FIG-170e16829af019eb", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (Blockarchitektur / High-Level Architectural View) der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong>\n<ul class=\"fig-list\"><li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform (Release R17-03 / AP R1.1.0) oberhalb der Ausführungsumgebung (<code>(Virtual) Machine / Hardware</code>).\n</li><li>Etabliert die Zweiteilung der Plattform-Funktionalitäten in <strong>Adaptive Platform Foundation</strong> (lokale Bibliotheks-/C++-APIs im Prozesskontext bzw. OS-Kernel) und <strong>Adaptive Platform Services</strong> (als eigenständige Prozesse realisierte, serviceorientierte Plattform-Dienste).\n</li><li>Spezifiziert die Schnittstellenebene <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> als einheitliche Laufzeitschnittstelle für Adaptive Applications (<code>aa</code>) und Non-Platform Services.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Ausführungsdomänen (von unten nach oben)</h5>\n<ol class=\"fig-list\"><li><strong>(Virtual) Machine / Hardware:</strong>\n<ul class=\"fig-list\"><li>Physische CPU/SoC-Ressourcen (POSIX-kompatible Mehrkernprozessoren, MMU) oder Hypervisor-basierte virtuelle Maschinen (VM/Guest-OS).\n</li></ul>\n</li><li><strong>Adaptive Platform Foundation (Blau hinterlegt):</strong>\n<ul class=\"fig-list\"><li>Stellt fundamentale Betriebssystem- und Middleware-Primitive bereit; interagiert primär über C++-Sprachbindungen / statisch bzw. dynamisch gelinkte Bibliotheks-APIs im Kontext der Applikationsprozesse:\n<ul class=\"fig-list\"><li><strong>Bootloader:</strong> Initialisierung der Hardware und Laden des Kernels (keine direkte ARA-Exposition).\n</li><li><strong>Operating System:</strong> POSIX-PSE51-konformes Multithreading/Multiprocessing-OS inklusive Speicher- und Prozessisolation.\n</li><li><strong>Execution Management (EM):</strong> Start/Stopp-Management von Prozessen, Manifest-basiertes Deployment, Maschinenzustands- und Funktionsgruppen-Zustandsverwaltung via API.\n</li><li><strong>Communication Management (CM):</strong> Serviceorientierte Kommunikation (SOME/IP, IPC, ara::com).\n</li><li><strong>Logging and Tracing (LOG):</strong> Standardisiertes Logging/Tracing (LT-Protokoll / DLT-Integration) via API.\n</li><li><strong>Persistency (PER):</strong> Zugriff auf nichtflüchtigen Speicher (Key-Value-Storage, File-Storage) via API.\n</li><li><strong>Hardware Acceleration:</strong> Standardisierte Schnittstellen für Rechenbeschleuniger (GPU, DSP, NPU / z. B. OpenVX/OpenCL).\n</li><li><strong>Platform Health Management (PHM):</strong> Überwachung von Aliveness, Deadline und Logical Supervision via API.\n</li><li><strong>Other Functional Clusters:</strong> Erweiterbare Foundation-Cluster (z. B. Time Synchronization / TS).\n</li></ul>\n</li></ul>\n</li><li><strong>Adaptive Platform Services (Grau hinterlegt):</strong>\n<ul class=\"fig-list\"><li>Plattform-Funktionalitäten, die architektonisch als Service-Provider (über ara::com bzw. IPC) instanziiert werden und über Service-Schnittstellen (<code>Service</code>) mit Clients kommunizieren:\n<ul class=\"fig-list\"><li><strong>Software Configuration Management (UCM / Software Management):</strong> Update-, Konfigurations- und Paketmanagement.\n</li><li><strong>Diagnostics (DM):</strong> Diagnoseverwaltung (UDS over IP / DoIP, ISO 14229) und Fault-Memory-Handling.\n</li><li><strong>Security Management (SM / Crypto / IAM):</strong> Identity- &amp; Access-Management, Schlüsselverwaltung, Krypto-Services.\n</li><li><strong>Other Adaptive Platform Services:</strong> Zukünftige/optionale standardisierte AP-Dienste.\n</li></ul>\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong>\n<ul class=\"fig-list\"><li>Die Abstraktionsgrenze. Setzt sich zusammen aus:\n<ul class=\"fig-list\"><li><strong>C++ API Interface (<code>API</code>):</strong> Direkte Header/Bibliotheks-Calls in Foundation-Cluster.\n</li><li><strong>Service Proxies / Skeletons (<code>Service</code>):</strong> Über <code>Communication Management</code> geroutete Service-Interfaces zu Platform- und Non-Platform-Services.\n</li></ul>\n</li></ul>\n</li><li><strong>Applikationsebene (Gelb hinterlegt):</strong>\n<ul class=\"fig-list\"><li><strong>Application:</strong> Standard-Adaptive-Applications (User-Space-Prozesse).\n</li><li><strong>Non-platform service:</strong> Kundenspezifische oder Third-Party-Services, die ihrerseits als Service-Provider im Gesamtsystem fungieren.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Interaktionspfade</h4>\n<ul class=\"fig-list\"><li><strong>Foundation-Interaktion (In-Process / Direct API):</strong>\n<ul class=\"fig-list\"><li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).\n</li><li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).\n</li></ul>\n</li><li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong>\n<ul class=\"fig-list\"><li>Find-Service → Subscribe / Offer-Service → Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.\n</li><li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.\n</li><li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong>\n<ul class=\"fig-list\"><li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.\n</li><li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest → Proxy/Skeleton-Artefakte) unterscheiden.\n</li></ul>\n</li><li><strong>Manifest- &amp; Konfigurationspflichten:</strong>\n<ul class=\"fig-list\"><li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).\n</li></ul>\n</li><li><strong>Boot- und Startup-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ce926fc9d8b43da7", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (High-Level Architectural View) der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong>\n<ul class=\"fig-list\"><li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform oberhalb der physischen bzw. virtualisierten Recheneinheit (<code>Machine</code>).\n</li><li>Strukturiert die Plattform in die beiden Hauptbereiche <strong>Adaptive Platform Foundation</strong> (Bibliotheks- und Kernel-APIs im Prozesskontext) und <strong>Adaptive Platform Services</strong> (serviceorientierte Plattformdienste).\n</li><li>Spezifiziert die Schnittstellenebene <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> als Abstraktionsschicht für <strong>User Applications</strong> (bestehend aus Standard-Applikationen und anwendungsspezifischen Services).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Ausführungsdomänen (von unten nach oben)</h5>\n<ol class=\"fig-list\"><li><strong>Machine:</strong>\n<ul class=\"fig-list\"><li>Physische Rechenknoten oder Hypervisor-basierte Instanzen.\n</li></ul>\n</li><li><strong>Adaptive Platform Foundation:</strong>\n<ul class=\"fig-list\"><li>Stellt grundlegende Systemdienste und Middleware-Primitiven über standardisierte C++-Schnittstellen (<code>API</code>) bereit:\n<ul class=\"fig-list\"><li><strong>Operating System:</strong> POSIX-basiertes Betriebssystem (Prozess- und Speicherisolation).\n</li><li><strong>Execution Management:</strong> Prozesslebenszyklus- und Zustandsverwaltung.\n</li><li><strong>Communication Management:</strong> Serviceorientierte Interprozess- und Netzwerkkonfiguration.\n</li><li><strong>Persistency:</strong> Nichtflüchtiger Datenspeicher.\n</li><li><strong>Platform Health Management:</strong> Überwachung der Prozessausführung und Deadlines.\n</li><li><strong>Time Synchronization:</strong> Verteilte Uhrensynchronisation.\n</li><li><strong>Identity Access Management:</strong> Identitätsprüfung und Zugriffskontrolle.\n</li><li><strong>Cryptography:</strong> Kryptografische Operationen und Schlüsselverwaltung.\n</li><li><strong>Logging and Tracing:</strong> Standardisiertes Logging und Tracing.\n</li><li><strong>REST:</strong> Webservices und HTTP-basierte Schnittstellen.\n</li></ul>\n</li></ul>\n</li><li><strong>Adaptive Platform Services:</strong>\n<ul class=\"fig-list\"><li>Eigenständige Plattform-Dienstprozesse, die über serviceorientierte Kommunikationsschnittstellen (<code>Service</code>) bereitgestellt werden:\n<ul class=\"fig-list\"><li><strong>Update &amp; Configuration Management:</strong> Software-Aktualisierung und Paketmanagement.\n</li><li><strong>Diagnostics:</strong> Fahrzeug- und Systemdiagnose (UDS/DoIP).\n</li><li><strong>Signal-2-Service Mapping:</strong> Übersetzung zwischen signalbasierten Bussystemen (z. B. CAN/LIN) und serviceorientierten Schnittstellen.\n</li><li><strong>Network Management:</strong> Koordination des Netzwerkzustands und Kommunikationsbereitschaft.\n</li></ul>\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong>\n<ul class=\"fig-list\"><li>Übergreifende Laufzeitschnittstelle aus direkten C++-APIs (<code>API</code>) und Service-Schnittstellen (<code>Service</code>).\n</li></ul>\n</li><li><strong>User Applications:</strong>\n<ul class=\"fig-list\"><li>Ausführungsebene oberhalb der ARA, unterteilt in klassische adaptive Applikationen (<code>Application</code>) und anwendungsspezifische Nicht-Plattform-Dienste (<code>Non-platform service</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Foundation-Interaktion (In-Process / Direct API):</strong>\n<ul class=\"fig-list\"><li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).\n</li><li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).\n</li></ul>\n</li><li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong>\n<ul class=\"fig-list\"><li>Find-Service → Subscribe / Offer-Service → Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.\n</li><li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.\n</li><li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong>\n<ul class=\"fig-list\"><li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.\n</li><li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest → Proxy/Skeleton-Artefakte) unterscheiden.\n</li></ul>\n</li><li><strong>Manifest- &amp; Konfigurationspflichten:</strong>\n<ul class=\"fig-list\"><li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).\n</li></ul>\n</li><li><strong>Boot- und Startup-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-99c8ebb58db9d95c", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (High-Level Architectural View) der AUTOSAR Adaptive Platform (AP) mit expliziter Kennzeichnung funktionaler Cluster (FCs).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong>\n<ul class=\"fig-list\"><li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform über der Basisschicht <code>(Virtual) Machine / Container / Hardware</code>.\n</li><li>Führt eine standardisierte Taxonomie und Namenskonvention für funktionale Cluster ein: Unterscheidung zwischen Foundation-Clustern (<code>API Platform Foundation FCs</code>, C++-Bibliotheken im Applikationsprozess) und Service-Clustern (<code>SERVICE Platform Service FCs</code>, als eigenständige Serverprozesse via IPC/SOME/IP angesprochen).\n</li><li>Schnittstellenebene <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> kapselt alle Cluster gegenüber <strong>User Applications</strong> (<code>Adaptive Application</code> und anwendungsdefinierte Nicht-Plattform-Services <code>ASW::* Non-PF Service</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Ausführungsdomänen (von unten nach oben)</h5>\n<ol class=\"fig-list\"><li><strong>(Virtual) Machine / Container / Hardware:</strong>\n<ul class=\"fig-list\"><li>Zugrundeliegende Ausführungsumgebung: Bare-Metal-Hardware, Hypervisor-VMs oder OS-Container.\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive Applications (ARA) / Platform FCs:</strong>\n<ul class=\"fig-list\"><li><strong>Platform Foundation FCs (über <code>API</code> angebunden):</strong>\n<ul class=\"fig-list\"><li><strong>POSIX PSE51 / C++ STL (Operating System):</strong> POSIX-Schnittstelle und C++ Standardbibliothek.\n</li><li><strong>ara::core (Core Types):</strong> Grundlegende Datentypen, Fehlerbehandlung (<code>Result</code>) und Hilfsklassen.\n</li><li><strong>ara::exec (Execution Mgmt.):</strong> Prozessinitialisierung, Scheduling und Funktionsgruppen.\n</li><li><strong>ara::com (Communication Mgmt.):</strong> Transportunabhängige Middleware, untergliedert in Transportbindungen <code>SOME/IP</code>, <code>IPC (local)</code> und <code>DDS</code>.\n</li><li><strong>ara::rest (RESTful):</strong> REST-Client/Server-Konnektivität.\n</li><li><strong>ara::per (Persistency):</strong> Persistenter Speicher (Key-Value, File).\n</li><li><strong>ara::tsync (Time Synchronization):</strong> Zeitquellen-Synchronisation.\n</li><li><strong>ara::phm (Platform Health Mgmt.):</strong> Alive-/Deadline-/Logical-Supervision.\n</li><li><strong>ara::iam (Identity Access Mgmt.):</strong> Zugriffsrechte und Policy Enforcement.\n</li><li><strong>ara::log (Logging &amp; Tracing):</strong> Strukturierte Protokollierung.\n</li><li><strong>ara::crypto (Cryptography):</strong> Krypto-Operationen und Zertifikatsmanagement.\n</li></ul>\n</li><li><strong>Platform Service FCs (über <code>SERVICE</code> angebunden):</strong>\n<ul class=\"fig-list\"><li><strong>ara::sm service (State Management):</strong> Zentrale Steuerung von Systemzuständen und Funktionsgruppen.\n</li><li><strong>ara::diag service (Diagnostics):</strong> Diagnose-Routing und Fehlerspeicher.\n</li><li><strong>ara::s2s service (Signal to Service Mapping):</strong> Signal-Service-Gateway für klassische Feldbusse.\n</li><li><strong>ara::nm service (Network Management):</strong> Bus- und Teilnetzwerk-Management.\n</li><li><strong>ara::ucm service (Update and Configuration Management):</strong> Paketinstallation und Softwareaktualisierung.\n</li></ul>\n</li></ul>\n</li><li><strong>User Applications:</strong>\n<ul class=\"fig-list\"><li>Vier Instanzen/Blöcke von <code>Adaptive Application</code>.\n</li><li>Anwendungsbezogene Services: <code>ASW::XYZ Non-PF Service</code> und <code>ASW::ABC Non-PF Service</code>.\n</li></ul>\n</li><li><strong>Legende (Legend):</strong>\n<ul class=\"fig-list\"><li><code>SERVICE Non-PF Service</code> (orange hinterlegt).\n</li><li><code>SERVICE Platfrom Service FCs</code> (grau hinterlegt mit Service-Balken).\n</li><li><code>API Platform Foundation FCs</code> (hellblau hinterlegt mit API-Balken).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Foundation-Interaktion (In-Process / Direct API):</strong>\n<ul class=\"fig-list\"><li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).\n</li><li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).\n</li></ul>\n</li><li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong>\n<ul class=\"fig-list\"><li>Find-Service → Subscribe / Offer-Service → Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.\n</li><li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.\n</li><li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong>\n<ul class=\"fig-list\"><li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.\n</li><li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest → Proxy/Skeleton-Artefakte) unterscheiden.\n</li></ul>\n</li><li><strong>Manifest- &amp; Konfigurationspflichten:</strong>\n<ul class=\"fig-list\"><li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).\n</li></ul>\n</li><li><strong>Boot- und Startup-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f899d4a45b4135d6", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (High-Level Architectural View) der AUTOSAR Adaptive Platform (AP) mit expliziter Kennzeichnung funktionaler Cluster (FCs).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong>\n<ul class=\"fig-list\"><li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform über der Basisschicht <code>(Virtual) Machine / Container / Hardware</code>.\n</li><li>Führt eine standardisierte Taxonomie und Namenskonvention für funktionale Cluster ein: Unterscheidung zwischen Foundation-Clustern (<code>API Platform Foundation FCs</code>, C++-Bibliotheken im Applikationsprozess) und Service-Clustern (<code>SERVICE Platform Service FCs</code>, als eigenständige Serverprozesse via IPC/SOME/IP angesprochen).\n</li><li>Schnittstellenebene <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> kapselt alle Cluster gegenüber <strong>User Applications</strong> (<code>Adaptive Application</code> und anwendungsdefinierte Nicht-Plattform-Services <code>ASW::* Non-PF Service</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Ausführungsdomänen (von unten nach oben)</h5>\n<ol class=\"fig-list\"><li><strong>(Virtual) Machine / Container / Hardware:</strong>\n<ul class=\"fig-list\"><li>Zugrundeliegende Ausführungsumgebung: Bare-Metal-Hardware, Hypervisor-VMs oder OS-Container.\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive Applications (ARA) / Platform FCs:</strong>\n<ul class=\"fig-list\"><li><strong>Platform Foundation FCs (über <code>API</code> angebunden):</strong>\n<ul class=\"fig-list\"><li><strong>POSIX PSE51 / C++ STL (Operating System Interface):</strong> POSIX-Schnittstelle und C++ Standardbibliothek.\n</li><li><strong>ara::core (Core Types):</strong> Grundlegende Datentypen und Basisfunktionalitäten.\n</li><li><strong>ara::exec (Execution Management):</strong> Prozesslebenszyklus- und Ausführungssteuerung.\n</li><li><strong>ara::com (Communication Management.):</strong> Kommunikationsmiddleware mit Bindungen <code>SOME/IP</code>, <code>IPC (local)</code> und <code>DDS</code>.\n</li><li><strong>ara::rest (RESTful):</strong> REST-Schnittstellen.\n</li><li><strong>ara::per (Persistency):</strong> Persistente Datenspeicherung.\n</li><li><strong>ara::tsync (Time Synchronization):</strong> Zeitsynchronisation.\n</li><li><strong>ara::phm (Platform Health Management):</strong> Plattform-Gesundheits- und Prozessüberwachung.\n</li><li><strong>ara::iam (Identity and Access Management):</strong> Zugriffskontrolle und Identitätsverwaltung.\n</li><li><strong>ara::log (Log and Trace):</strong> Logging- und Tracing-Framework.\n</li><li><strong>ara::crypto (Cryptography):</strong> Kryptografie-Dienste.\n</li></ul>\n</li><li><strong>Platform Service FCs (über <code>SERVICE</code> angebunden):</strong>\n<ul class=\"fig-list\"><li><strong>ara::sm service (State Management):</strong> Zustandsverwaltung und Koordination.\n</li><li><strong>ara::diag service (Diagnostics):</strong> Diagnoseprotokolle und Fehlermanagement.\n</li><li><strong>ara::s2s service (Signal to Service Mapping):</strong> Transformation signalbasierter Kommunikation in Services.\n</li><li><strong>ara::nm service (Network Management):</strong> Netzwerkmanagement.\n</li><li><strong>ara::ucm service (Update and Config Management):</strong> Software-Update- und Konfigurationsmanagement.\n</li></ul>\n</li></ul>\n</li><li><strong>User Applications:</strong>\n<ul class=\"fig-list\"><li>Vier <code>Adaptive Application</code>-Instanzen.\n</li><li>Nicht-Plattform-Services <code>ASW::XYZ Non-PF Service</code> und <code>ASW::ABC Non-PF Service</code>.\n</li></ul>\n</li><li><strong>Legende (Key):</strong>\n<ul class=\"fig-list\"><li><code>SERVICE Non-PF Service</code> (orange).\n</li><li><code>SERVICE Platform Service FCs</code> (grau).\n</li><li><code>API Platform Foundation FCs</code> (blau).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Foundation-Interaktion (In-Process / Direct API):</strong>\n<ul class=\"fig-list\"><li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).\n</li><li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).\n</li></ul>\n</li><li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong>\n<ul class=\"fig-list\"><li>Find-Service → Subscribe / Offer-Service → Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.\n</li><li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.\n</li><li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong>\n<ul class=\"fig-list\"><li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.\n</li><li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest → Proxy/Skeleton-Artefakte) unterscheiden.\n</li></ul>\n</li><li><strong>Manifest- &amp; Konfigurationspflichten:</strong>\n<ul class=\"fig-list\"><li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).\n</li></ul>\n</li><li><strong>Boot- und Startup-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-90d9ec5b03eb9ee3", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (High-Level Architectural View) der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong>\n<ul class=\"fig-list\"><li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform über der Basisschicht <code>(Virtual) Machine / Container / Hardware</code>.\n</li><li>Weist funktionale Cluster verbindlich den Bereichen <strong>Platform Foundation FCs</strong> (<code>API</code>, C++-Bibliotheken) und <strong>Platform Service FCs</strong> (<code>SERVICE</code>, eigenständige Prozesse via IPC/SOME/IP) zu.\n</li><li>Stellt die <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> als Abstraktionsebene für <strong>User Applications</strong> bereit, wobei Signal-to-Service-Transformation als Protokollbindung (<code>Signal PDU</code>) direkt in <code>ara::com</code> integriert und Diagnose (<code>ara::diag</code>) als Foundation-Cluster modelliert ist.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Ausführungsdomänen (von unten nach oben)</h5>\n<ol class=\"fig-list\"><li><strong>(Virtual) Machine / Container / Hardware:</strong>\n<ul class=\"fig-list\"><li>Physische oder virtualisierte Plattform (Bare-Metal, VM, Container).\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive Applications (ARA) / Platform FCs:</strong>\n<ul class=\"fig-list\"><li><strong>Platform Foundation FCs (über <code>API</code> angebunden):</strong>\n<ul class=\"fig-list\"><li><strong>POSIX PSE51 / C++ STL (Operating System Interface):</strong> Betriebssystemschnittstelle nach POSIX PSE51 und C++ Standardbibliothek.\n</li><li><strong>ara::core (Core Types):</strong> Grundlegende Typen und Primitive.\n</li><li><strong>ara::exec (Execution Management):</strong> Zustands-, Prozess- und Ressourcenverwaltung.\n</li><li><strong>ara::com (Communication Management.):</strong> Kommunikationsmiddleware mit den Transport- und Protokollbindungen <code>IPC</code>, <code>Signal PDU</code>, <code>SOME/IP</code> und <code>DDS</code>.\n</li><li><strong>ara::rest (RESTful):</strong> RESTful Web-Services.\n</li><li><strong>ara::per (Persistency):</strong> Persistente Datenspeicherung.\n</li><li><strong>ara::tsync (Time Synchronization):</strong> Uhrensynchronisation.\n</li><li><strong>ara::phm (Platform Health Management):</strong> Health Monitoring und Überwachungsfunktionen.\n</li><li><strong>ara::diag (Diagnostics):</strong> Diagnoseschnittstelle im Prozesskontext der Applikation.\n</li><li><strong>ara::iam (Identity and Access Management):</strong> Autorisierung und Richtliniendurchsetzung.\n</li><li><strong>ara::log (Log and Trace):</strong> Diagnose- und Entwicklungs-Logging/-Tracing.\n</li><li><strong>ara::crypto (Cryptography):</strong> Kryptografische Primitive und Schlüsselverwaltung.\n</li></ul>\n</li><li><strong>Platform Service FCs (über <code>SERVICE</code> angebunden):</strong>\n<ul class=\"fig-list\"><li><strong>ara::sm service (State Management):</strong> Globales System- und Funktionsgruppen-Zustandsmanagement.\n</li><li><strong>ara::ucm service (Update and Config Management):</strong> Paket-, Software- und Update-Management.\n</li><li><strong>ara::nm service (Network Management):</strong> Netzwerk-Zustandsmanagement.\n</li></ul>\n</li></ul>\n</li><li><strong>User Applications:</strong>\n<ul class=\"fig-list\"><li>Drei <code>Adaptive Application</code>-Instanzen.\n</li><li>Nicht-Plattform-Services <code>ASW::XYZ Non-PF Service</code> und <code>ASW::ABC Non-PF Service</code>.\n</li></ul>\n</li><li><strong>Legende (Key):</strong>\n<ul class=\"fig-list\"><li><code>SERVICE Non-PF Service</code> (orange).\n</li><li><code>SERVICE Platform Service FCs</code> (grau).\n</li><li><code>API Platform Foundation FCs</code> (blau).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Foundation-Interaktion (In-Process / Direct API):</strong>\n<ul class=\"fig-list\"><li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).\n</li><li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).\n</li></ul>\n</li><li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong>\n<ul class=\"fig-list\"><li>Find-Service → Subscribe / Offer-Service → Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.\n</li><li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.\n</li><li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong>\n<ul class=\"fig-list\"><li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.\n</li><li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest → Proxy/Skeleton-Artefakte) unterscheiden.\n</li></ul>\n</li><li><strong>Manifest- &amp; Konfigurationspflichten:</strong>\n<ul class=\"fig-list\"><li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).\n</li></ul>\n</li><li><strong>Boot- und Startup-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d642ff7e58895e5c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (High-Level Architectural View) der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong>\n<ul class=\"fig-list\"><li>Definiert die logische Gliederung der AUTOSAR Adaptive Platform über der Basisschicht <code>(Virtual) Machine / Container / Hardware</code>.\n</li><li>Weist funktionale Cluster verbindlich den Bereichen <strong>Platform Foundation FCs</strong> (<code>API</code>, C++-Bibliotheken) und <strong>Platform Service FCs</strong> (<code>SERVICE</code>, eigenständige Prozesse via IPC/SOME/IP) zu.\n</li><li>Stellt die <strong>ARA (AUTOSAR Runtime for Adaptive Applications)</strong> als Abstraktionsebene für <strong>User Applications</strong> bereit, wobei Signal-to-Service-Transformation als Protokollbindung (<code>Signal PDU</code>) direkt in <code>ara::com</code> integriert und Diagnose (<code>ara::diag</code>) als Foundation-Cluster modelliert ist.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Ausführungsdomänen (von unten nach oben)</h5>\n<ol class=\"fig-list\"><li><strong>(Virtual) Machine / Container / Hardware:</strong>\n<ul class=\"fig-list\"><li>Physische oder virtualisierte Plattform (Bare-Metal, VM, Container).\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive Applications (ARA) / Platform FCs:</strong>\n<ul class=\"fig-list\"><li><strong>Platform Foundation FCs (über <code>API</code> angebunden):</strong>\n<ul class=\"fig-list\"><li><strong>POSIX PSE51 / C++ STL (Operating System Interface):</strong> POSIX PSE51 und C++ STL Betriebssystemschnittstelle.\n</li><li><strong>ara::core (Core):</strong> Basistypen und Kernprimitive der Adaptive Platform.\n</li><li><strong>ara::exec (Execution Management):</strong> Start, Stopp und Überwachung von Prozessen.\n</li><li><strong>ara::com (Communication Management.):</strong> Serviceorientierte Kommunikation mit Bindungen <code>IPC</code>, <code>Signal PDU</code>, <code>SOME/IP</code> und <code>DDS</code>.\n</li><li><strong>ara::rest (REST):</strong> REST-Webservices.\n</li><li><strong>ara::per (Persistency):</strong> Nichtflüchtige Datenspeicherung.\n</li><li><strong>ara::tsync (Time Synchronization):</strong> Synchronisation von Zeitbasen.\n</li><li><strong>ara::phm (Platform Health Management):</strong> Alive-, Deadline- und logische Überwachung.\n</li><li><strong>ara::diag (Diagnostics):</strong> Diagnoseschnittstelle.\n</li><li><strong>ara::iam (Identity and Access Management):</strong> Identitäts- und Rechtemanagement.\n</li><li><strong>ara::log (Log and Trace):</strong> Logging und Tracing.\n</li><li><strong>ara::crypto (Cryptography):</strong> Kryptografische Algorithmen und Zertifikate.\n</li></ul>\n</li><li><strong>Platform Service FCs (über <code>SERVICE</code> angebunden):</strong>\n<ul class=\"fig-list\"><li><strong>ara::sm service (State Management):</strong> Plattformweites Zustandsmanagement.\n</li><li><strong>ara::ucm service (Update and Config Management):</strong> Update- und Konfigurationsverwaltung.\n</li><li><strong>ara::nm service (Network Management):</strong> Netzwerkmanagement.\n</li></ul>\n</li></ul>\n</li><li><strong>User Applications:</strong>\n<ul class=\"fig-list\"><li>Drei <code>Adaptive Application</code>-Instanzen.\n</li><li>Nicht-Plattform-Services <code>ASW::XYZ Non-PF Service</code> und <code>ASW::ABC Non-PF Service</code>.\n</li></ul>\n</li><li><strong>Legende (Key):</strong>\n<ul class=\"fig-list\"><li><code>SERVICE Non-PF Service</code> (orange).\n</li><li><code>SERVICE Platform Service FCs</code> (grau).\n</li><li><code>API Platform Foundation FCs</code> (blau).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Foundation-Interaktion (In-Process / Direct API):</strong>\n<ul class=\"fig-list\"><li>Direkter synchroner oder deterministisch asynchroner Aufruf über C++14/C++17-Klassen (z. B. <code>ara::log::Logger</code>, <code>ara::per::OpenFile()</code>, <code>ara::exec::ApplicationClient</code>).\n</li><li>Keine IPC-Roundtrips für Basisfunktionen wie Tracing, Persistenz-Zugriff oder EM-Zustandsrückmeldung (<code>ReportExecutionState</code>).\n</li></ul>\n</li><li><strong>Service-Interaktion (Inter-Process / Service-Oriented):</strong>\n<ul class=\"fig-list\"><li>Find-Service → Subscribe / Offer-Service → Method Call (Request/Response oder Fire-and-Forget) / Event Publication via <code>ara::com</code>.\n</li><li><strong>Asynchroner Pfad:</strong> Methodeninferenzen nutzen <code>ara::core::Future</code> / <code>ara::core::Promise</code> zur Entkopplung von Aufrufer- und Diensteprozessen.\n</li><li><strong>Fehlerbehandlung:</strong> Standardisierter Fehlerpfad über <code>ara::core::Result&lt;T, ara::core::ErrorCode&gt;</code> anstelle von C++-Exceptions (AUTOSAR-C++14-Regelsatz <code>A15-0-X</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Schnittstellenvertrag vs. Prozessisolation:</strong>\n<ul class=\"fig-list\"><li>Applikationen dürfen <strong>nicht</strong> direkt auf OS-Kernel-Treiber oder Hardware zugreifen. Jeglicher I/O- und Peripheriezugriff muss über die Foundation (z. B. POSIX OS, Hardware Acceleration) oder Services gekapselt werden.\n</li><li>Entwickler müssen zwischen Foundation-Clusters (Header-Include + Bibliothekslink) und Services (Code-Generierung via ARXML-Interface-Manifest → Proxy/Skeleton-Artefakte) unterscheiden.\n</li></ul>\n</li><li><strong>Manifest- &amp; Konfigurationspflichten:</strong>\n<ul class=\"fig-list\"><li>Jede Instanz (Application, Non-platform Service, Service) benötigt ein <code>ExecutionManifest</code> (Prozessinstanziierung, Resource-Limits, Scheduling-Policies) sowie ein <code>ServiceInstanceManifest</code> für die Bindung an Kommunikationsendpunkte (SOME/IP-Deployment, IPC-Binding).\n</li></ul>\n</li><li><strong>Boot- und Startup-Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Nach Übergabe der Kontrolle durch den <code>Bootloader</code> an das <code>Operating System</code> besitzt <code>Execution Management</code> die ausschließliche Hoheit über den Prozess-Lebenszyklus. Eigenmächtiges Forking/Spawnen von Subprozessen (<code>fork()</code>, <code>exec()</code>) durch Applikationen verletzt die Spezifikationsvorgaben.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-170e16829af019eb", "to": "FIG-ce926fc9d8b43da7", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>User Applications:</strong> Explizite Zusammenfassung der oberen Ebene unter der Bereichsbezeichnung <code>User Applications</code> (zuvor unbeschrifteter gelber Bereich).\n</li><li><strong>Adaptive Platform Foundation:</strong>\n<ul class=\"fig-list\"><li>Hinzugefügt: <code>REST</code> (mit <code>API</code>), <code>Identity Access Management</code> (mit <code>API</code>), <code>Cryptography</code> (mit <code>API</code>) und <code>Time Synchronization</code> (mit <code>API</code>).\n</li><li>Entfallen: <code>Hardware Acceleration</code>, <code>Other Functional Clusters</code> und <code>Bootloader</code>.\n</li></ul>\n</li><li><strong>Adaptive Platform Services:</strong>\n<ul class=\"fig-list\"><li>Hinzugefügt: <code>Signal-2-Service Mapping</code> (mit <code>Service</code>) und <code>Network Management</code> (mit <code>Service</code>).\n</li><li>Umbenannt: <code>Software Configuration Management</code> in <code>Update &amp; Configuration Management</code>.\n</li><li>Entfallen: <code>Other Adaptive Platform Services</code> sowie <code>Security Management</code> (aufgeteilt in IAM und Cryptography in der Foundation).\n</li></ul>\n</li><li><strong>Infrastruktur / Hardware:</strong> Umbenennung der Basisschicht von <code>(Virtual) Machine / Hardware</code> zu <code>Machine</code>.\n</li></ul>"}, {"from": "FIG-ce926fc9d8b43da7", "to": "FIG-99c8ebb58db9d95c", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Legende:</strong> Hinzufügung einer Legende (<code>Legend</code>) zur Unterscheidung von <code>SERVICE Non-PF Service</code>, <code>SERVICE Platfrom Service FCs</code> und <code>API Platform Foundation FCs</code>.\n</li><li><strong>Applikationsebene:</strong> Erweiterung auf vier <code>Adaptive Application</code>-Blöcke sowie Spezifikation der Non-Platform-Services als <code>ASW::XYZ Non-PF Service</code> und <code>ASW::ABC Non-PF Service</code>.\n</li><li><strong>Adaptive Platform Foundation:</strong>\n<ul class=\"fig-list\"><li>Einführung von Namespace-Präfixen: <code>ara::core Core Types</code>, <code>ara::com Communication Mgmt.</code>, <code>ara::rest RESTful</code>, <code>ara::tsync Time Synchronization</code>, <code>ara::per Persistency</code>, <code>ara::phm Platform Health Mgmt.</code>, <code>ara::exec Execution Mgmt.</code>, <code>ara::iam Identity Access Mgmt.</code>, <code>ara::log Logging &amp; Tracing</code>, <code>ara::crypto Cryptography</code>.\n</li><li>Detaillierung von <code>ara::com</code>: Vertikale Unterteilung in Transportbindungen <code>SOME/IP</code>, <code>IPC (local)</code> und <code>DDS</code>.\n</li><li>Umbenennung des Betriebssystems zu <code>POSIX PSE51 / C++ STL Operating System</code>.\n</li></ul>\n</li><li><strong>Adaptive Platform Services:</strong>\n<ul class=\"fig-list\"><li>Einführung von Namespace- und Servicemarkern: <code>ara::sm service State Management</code> (ersetzt EM-Zustandsverwaltung als separater Plattform-Service), <code>ara::diag service Diagnostics</code>, <code>ara::s2s service Signal to Service Mapping</code>, <code>ara::nm service Network Management</code>, <code>ara::ucm service Update and Configuration Management</code>.\n</li></ul>\n</li><li><strong>Basisschicht:</strong> Umbenennung von <code>Machine</code> zu <code>(Virtual) Machine / Container / Hardware</code>.\n</li></ul>"}, {"from": "FIG-99c8ebb58db9d95c", "to": "FIG-f899d4a45b4135d6", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Legende:</strong> Umbenennung der Überschrift von <code>Legend</code> zu <code>Key</code> sowie Korrektur des Tippfehlers in <code>Platfrom Service FCs</code> zu <code>Platform Service FCs</code>.\n</li><li><strong>Beschriftungen:</strong>\n<ul class=\"fig-list\"><li>Foundation: <code>ara::iam Identity Access Mgmt.</code> umbenannt in <code>ara::iam Identity and Access Management</code>; <code>ara::log Logging &amp; Tracing</code> umbenannt in <code>ara::log Log and Trace</code>; <code>POSIX PSE51 / C++ STL Operating System</code> umbenannt in <code>POSIX PSE51 / C++ STL Operating System Interface</code>.\n</li><li>Platform Services: <code>ara::ucm service Update and Configuration Management</code> umbenannt in <code>ara::ucm service Update and Config Management</code>.\n</li></ul>\n</li><li><strong>Layout:</strong> Entfernung des oberen Textfragments am Bildrand.\n</li></ul>"}, {"from": "FIG-f899d4a45b4135d6", "to": "FIG-90d9ec5b03eb9ee3", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Applikationsebene:</strong> Reduktion der <code>Adaptive Application</code>-Kacheln von vier auf drei.\n</li><li><strong>Verschiebung Diagnostics:</strong> <code>ara::diag Diagnostics</code> wechselt von den Platform Services (<code>SERVICE</code>) in die Adaptive Platform Foundation (<code>API</code>).\n</li><li><strong>Entfall Signal to Service Mapping:</strong> Das Cluster <code>ara::s2s service Signal to Service Mapping</code> entfällt als eigenständiger Platform Service; stattdessen wird <code>Signal PDU</code> als Bindung/Interface direkt in <code>ara::com</code> integriert (neben <code>IPC</code>, <code>SOME/IP</code> und <code>DDS</code>).\n</li><li><strong>Anordnung:</strong> <code>ara::sm service</code>, <code>ara::ucm service</code> und <code>ara::nm service</code> bilden nun die verbleibenden Platform Services. Foundation-Cluster werden im Raster neu angeordnet (<code>ara::diag</code>, <code>ara::log</code>, <code>ara::crypto</code>).\n</li></ul>"}, {"from": "FIG-90d9ec5b03eb9ee3", "to": "FIG-d642ff7e58895e5c", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>ara::core:</strong> Beschriftung von <code>ara::core Core Types</code> geändert zu <code>ara::core Core</code>.\n</li><li><strong>ara::rest:</strong> Beschriftung von <code>ara::rest RESTful</code> geändert zu <code>ara::rest REST</code>.\n</li></ul>"}]};
